function extractTerrainFromImage() {
  const off = document.createElement("canvas");
  off.width = GRID_N;
  off.height = GRID_N;
  const octx = off.getContext("2d");
  octx.drawImage(moonImg, 0, 0, GRID_N, GRID_N);
  const data = octx.getImageData(0, 0, GRID_N, GRID_N).data;

  imgBrightnessGrid = new Float32Array(GRID_N * GRID_N);
  imgGradientGrid = new Float32Array(GRID_N * GRID_N);
  imgGradXGrid = new Float32Array(GRID_N * GRID_N);
  imgGradYGrid = new Float32Array(GRID_N * GRID_N);

  for (let i = 0; i < GRID_N * GRID_N; i++) {
    const r = data[i * 4];
    const g = data[i * 4 + 1];
    const b = data[i * 4 + 2];
    imgBrightnessGrid[i] = (0.299 * r + 0.587 * g + 0.114 * b) / 255.0;
  }

  for (let y = 1; y < GRID_N - 1; y++) {
    for (let x = 1; x < GRID_N - 1; x++) {
      const idx = y * GRID_N + x;
      const gx = imgBrightnessGrid[idx + 1] - imgBrightnessGrid[idx - 1];
      const gy = imgBrightnessGrid[idx + GRID_N] - imgBrightnessGrid[idx - GRID_N];
      imgGradXGrid[idx] = gx;
      imgGradYGrid[idx] = gy;
      imgGradientGrid[idx] = Math.min(1.0, Math.sqrt(gx * gx + gy * gy) * 3.8);
    }
  }
}

const SIN_20 = Math.sin(20 * Math.PI / 180);

function latLonToNorm(lat, lon) {
  const colatRad = (90 + lat) * Math.PI / 180;
  const rNorm = Math.sin(colatRad) / SIN_20;
  const lonRad = lon * Math.PI / 180;
  return {
    nx: rNorm * Math.sin(lonRad),
    ny: -rNorm * Math.cos(lonRad),
    rNorm
  };
}

function normToLatLon(nx, ny) {
  const rNorm = Math.sqrt(nx * nx + ny * ny);
  if (rNorm > 1.0) return null;
  const sinColat = Math.min(1.0, rNorm * SIN_20);
  const colatDeg = Math.asin(sinColat) * 180 / Math.PI;
  const lat = -90 + colatDeg;
  let lon = Math.atan2(nx, -ny) * 180 / Math.PI;
  return { lat, lon, rNorm };
}

// Compute Lunar South Pole Ephemeris (Solar Azimuth, Sub-solar Lat, Optical Earth Libration) from Date/Time
function computeEphemerisFromInputs() {
  const dStr = document.getElementById("missionDate").value || "2026-11-15";
  const tStr = document.getElementById("missionTime").value || "16:30";
  const dt = new Date(`${dStr}T${tStr}:00Z`);
  const ms = isNaN(dt.getTime()) ? Date.UTC(2026, 10, 15, 16, 30) : dt.getTime();

  // Reference epoch: J2026.0
  const daysSinceRef = (ms - Date.UTC(2026, 0, 1, 0, 0, 0)) / 86400000.0;
  const synodicPeriod = 29.530589;
  const draconicYear = 346.62;
  const nodicalMonth = 27.2122;

  const sunAz = ((daysSinceRef / synodicPeriod) * 360.0 + 95.0) % 360.0;
  const sunAzNorm = sunAz > 180 ? sunAz - 360 : sunAz;
  // Sub-solar latitude oscillates between -1.54° (Southern Lunar Summer) and +1.54° (Southern Winter)
  const sunSubLat = -1.54 * Math.sin((2 * Math.PI * (daysSinceRef - 45)) / draconicYear);
  // Earth optical libration in latitude (+/- 6.68°) and longitude (+/- 7.9°)
  const earthLibLat = 6.68 * Math.sin((2 * Math.PI * daysSinceRef) / nodicalMonth + 0.7);
  const earthLibLon = 7.90 * Math.cos((2 * Math.PI * daysSinceRef) / 27.5545);

  state.sunAzimuthDeg = sunAzNorm;
  state.sunSubLatDeg = sunSubLat;
  state.earthLibLatDeg = earthLibLat;
  state.earthLibLonDeg = earthLibLon;

  updateEphemerisUI();
}

let jplRequestCounter = 0;

const jplCache = {};

async function fetchWithProxyFallback(targetUrl) {
  if (jplCache[targetUrl]) return jplCache[targetUrl];

  // Extraer los parámetros de la URL de la NASA para pasarlos a nuestro server.py local
  const queryString = targetUrl.split("?")[1];
  const localUrl = `/jpl?${queryString}`;

  try {
    const r = await fetch(localUrl);
    if (r.ok) {
      const parsed = await r.json();
      if (parsed && parsed.result) {
        jplCache[targetUrl] = parsed;
        return parsed;
      }
    }
  } catch (err) {
    console.warn("Aviso servidor local:", err.message);
  }

  throw new Error("JPL Horizons no disponible temporalmente");
}

async function fetchJPLHorizonsEphemeris(dStr, tStr) {
  const start = `${dStr} ${tStr}`;
  const dtObj = new Date(`${dStr}T${tStr}:00Z`);
  const ms = isNaN(dtObj.getTime()) ? Date.UTC(2026, 10, 15, 16, 30) : dtObj.getTime();
  const dtEnd = new Date(ms + 60000);
  const stop = dtEnd.toISOString().slice(0, 16).replace("T", " ");

  const buildNasaUrl = (targetId) => {
    const params = new URLSearchParams({
      format: "json",
      COMMAND: `'${targetId}'`,
      OBJ_DATA: "'NO'",
      MAKE_EPHEM: "'YES'",
      EPHEM_TYPE: "'OBSERVER'",
      CENTER: "'coord@301'",        // 301 = Luna
      COORD_TYPE: "'GEODETIC'",
      SITE_COORD: "'0,-89.5,0'",    // Polo Sur Lunar (Lon 0°, Lat 89.5°S)
      START_TIME: `'${start}'`,
      STOP_TIME: `'${stop}'`,
      STEP_SIZE: "'1 m'",
      QUANTITIES: "'4'"             // 4 = Azimut y Elevación aparentes
    });
    return `https://ssd.jpl.nasa.gov/api/horizons.api?${params.toString()}`;
  };

  const parseAzEl = (resultText) => {
    const match = resultText.match(/\$\$SOE([\s\S]*?)\$\$EOE/);
    if (!match) return null;
    const line = match[1].trim().split("\n")[0].trim();
    const nums = line.match(/[-+]?\d+\.\d+/g);
    if (!nums || nums.length < 2) return null;
    return {
      az: parseFloat(nums[nums.length - 2]),
      el: parseFloat(nums[nums.length - 1])
    };
  };

  const [sunRes, earthRes] = await Promise.all([
    fetchWithProxyFallback(buildNasaUrl("10")),   // 10 = Sol
    fetchWithProxyFallback(buildNasaUrl("399"))   // 399 = Tierra
  ]);

  const sun = parseAzEl(sunRes.result || "");
  const earth = parseAzEl(earthRes.result || "");
  if (!sun || !earth) throw new Error("Formato inesperado en respuesta de JPL Horizons");

  return { sun, earth };
}

function updateEphemerisUI() {
  const isEs = state.lang === "es";
  const azStr = `${state.sunAzimuthDeg >= 0 ? "+" : ""}${state.sunAzimuthDeg.toFixed(0)}°`;
  const latStr = `${state.sunSubLatDeg >= 0 ? "+" : ""}${state.sunSubLatDeg.toFixed(2)}°`;
  const libStr = `${state.earthLibLatDeg >= 0 ? "+" : ""}${state.earthLibLatDeg.toFixed(1)}°`;

  document.getElementById("ephemSunAz").textContent = isEs ? `Sol Az: ${azStr}` : `Sun Az: ${azStr}`;
  document.getElementById("ephemSunLat").textContent = isEs ? `Sol φ: ${latStr}` : `Sun φ: ${latStr}`;
  document.getElementById("ephemEarthLib").textContent = isEs ? `Lib. Tierra: ${libStr}` : `Earth Lib: ${libStr}`;

  // Actualizar el badge visual de estado (JPL Horizons vs Modelo Local)
  const badgeEl = document.getElementById("ephemSourceBadge");
  if (badgeEl) {
    if (state.ephemSource === "jpl") {
      badgeEl.textContent = "JPL HORIZONS LIVE";
      badgeEl.style.background = "rgba(16, 185, 129, 0.18)";
      badgeEl.style.color = "#10b981";
      badgeEl.style.border = "1px solid rgba(16, 185, 129, 0.45)";
    } else if (state.ephemSource === "loading") {
      badgeEl.textContent = isEs ? "SINCRONIZANDO JPL..." : "SYNCING JPL...";
      badgeEl.style.background = "rgba(56, 189, 248, 0.16)";
      badgeEl.style.color = "#38bdf8";
      badgeEl.style.border = "1px solid rgba(56, 189, 248, 0.4)";
    } else {
      badgeEl.textContent = isEs ? "MODELO ANALÍTICO" : "ANALYTIC MODEL";
      badgeEl.style.background = "rgba(245, 158, 11, 0.16)";
      badgeEl.style.color = "#f59e0b";
      badgeEl.style.border = "1px solid rgba(245, 158, 11, 0.4)";
    }
  }

  const seasonGood = state.sunSubLatDeg < 0;
  const earthGood = state.earthLibLatDeg > 0;
  const impactEl = document.getElementById("missionTimeImpact");

  const sourceNoteEs = state.ephemSource === "jpl"
    ? `<span style="color:#10b981; font-weight:600;">[✓ Telemetría real NASA JPL Horizons API]</span>`
    : `<span style="color:#94a3b8;">[Modelo orbital analítico local J2026.0]</span>`;

  const sourceNoteEn = state.ephemSource === "jpl"
    ? `<span style="color:#10b981; font-weight:600;">[✓ Live NASA JPL Horizons API telemetry]</span>`
    : `<span style="color:#94a3b8;">[Local analytic orbital model J2026.0]</span>`;

  if (isEs) {
    impactEl.innerHTML =
      `• <b>Iluminación (${seasonGood ? "Verano Polar Sur" : "Invierno Polar Sur"}):</b> El Sol entra desde el meridiano <b>${azStr}</b>. ${seasonGood ? "La inclinación solar negativa favorece mayor luz continua en las crestas." : "Las sombras de los cráteres se alargan, reduciendo la energía solar."}<br>` +
      `• <b>Enlace Tierra (Libración ${libStr}):</b> ${earthGood ? "La Tierra se eleva sobre el horizonte polar (+DTE%), facilitando comunicaciones continuas." : "La Tierra baja hacia el horizonte, aumentando el bloqueo por montañas cercanas."}<br>` +
      `<div style="margin-top:4px; font-size:10px;">${sourceNoteEs}</div>`;
  } else {
    impactEl.innerHTML =
      `• <b>Illumination (${seasonGood ? "South Polar Summer" : "South Polar Winter"}):</b> Sunlight arrives from meridian <b>${azStr}</b>. ${seasonGood ? "Negative sub-solar latitude boosts continuous sunlight on ridges." : "Crater shadows lengthen, reducing available solar power."}<br>` +
      `• <b>Earth Link (Libration ${libStr}):</b> ${earthGood ? "Earth rises higher above the polar horizon (+DTE%), improving continuous comms." : "Earth dips lower on the horizon, increasing terrain masking risk."}<br>` +
      `<div style="margin-top:4px; font-size:10px;">${sourceNoteEn}</div>`;
  }
}

async function onDateTimeChange() {
  const reqId = ++jplRequestCounter;

  // 1. Respuesta inmediata con el modelo analítico local mientras carga JPL
  state.ephemSource = "loading";
  computeEphemerisFromInputs();
  rebuildThermalLayer();
  updateTelemetry();
  render();

  const dStr = document.getElementById("missionDate").value || "2026-11-15";
  const tStr = document.getElementById("missionTime").value || "16:30";

  // 2. Consulta asíncrona a NASA JPL Horizons
  try {
    const jpl = await fetchJPLHorizonsEphemeris(dStr, tStr);
    if (reqId !== jplRequestCounter) return; // Ignorar si el usuario ya cambió a otra fecha

    state.sunAzimuthDeg = jpl.sun.az > 180 ? jpl.sun.az - 360 : jpl.sun.az;
    state.sunSubLatDeg = -jpl.sun.el;
    state.earthLibLatDeg = jpl.earth.el;
    state.earthLibLonDeg = jpl.earth.az > 180 ? jpl.earth.az - 360 : jpl.earth.az;
    state.ephemSource = "jpl";

    updateEphemerisUI();
    rebuildThermalLayer();
    updateTelemetry();
    render();
  } catch (err) {
    if (reqId !== jplRequestCounter) return;
    state.ephemSource = "local";
    updateEphemerisUI();
    console.warn("[JPL Horizons Fallback]:", err.message);
  }
}

function stepMissionDays(deltaDays) {
  const dInput = document.getElementById("missionDate");
  const dStr = dInput.value || "2026-11-15";
  const dt = new Date(`${dStr}T12:00:00Z`);
  dt.setUTCDate(dt.getUTCDate() + deltaDays);
  dInput.value = dt.toISOString().slice(0, 10);
  onDateTimeChange();
}

// Evaluate physical terrain metrics & LSI at normalized disk coordinates (nx, ny)
function evaluatePoint(nx, ny) {
  const rNorm = Math.sqrt(nx * nx + ny * ny);
  if (rNorm > 1.0) return null;

  const u = 0.5 + nx * 0.485;
  const v = 0.5 + ny * 0.485;

  let lum = 0.5;
  let grad = 0.25;
  let gx = 0.0, gy = 0.0;
  if (imgBrightnessGrid) {
    const ix = Math.max(0, Math.min(GRID_N - 1, Math.floor(u * GRID_N)));
    const iy = Math.max(0, Math.min(GRID_N - 1, Math.floor(v * GRID_N)));
    const idx = iy * GRID_N + ix;
    lum = imgBrightnessGrid[idx];
    grad = imgGradientGrid[idx];
    gx = imgGradXGrid[idx];
    gy = imgGradYGrid[idx];
  }

  // Convert (nx, ny) to selenographic lon/lat for directional solar & Earth visibility physics
  const sinColat = Math.min(1.0, rNorm * SIN_20);
  const colatDeg = Math.asin(sinColat) * 180 / Math.PI;
  const lat = -90 + colatDeg;
  const lon = Math.atan2(nx, -ny) * 180 / Math.PI;

  // Ephemeris directional solar modulation based on selected Date & Time
  const sunAzRad = state.sunAzimuthDeg * Math.PI / 180;
  const sunDirX = Math.sin(sunAzRad);
  const sunDirY = -Math.cos(sunAzRad);
  const aspectDot = -(gx * sunDirX + gy * sunDirY) * 28.0;
  const seasonalBoost = (-state.sunSubLatDeg / 1.54) * 7.5; // +7.5% in south summer, -7.5% in winter

  const polarFactor = 1.0 - rNorm * 0.35;
  const shadowPenalty = lum < 0.26 ? (0.26 - lum) * 38.0 : 0.0;
  const slope = Math.max(1.2, Math.min(32.0, 2.5 + grad * 21.0 + shadowPenalty * 0.45));
  const roughness = Math.max(0.08, Math.min(1.65, 0.12 + grad * 0.95 + (lum < 0.22 ? 0.28 : 0.0)));

  const rawSolar = (lum * 108.0) * (0.85 + 0.15 * polarFactor) + aspectDot + seasonalBoost;
  const solar = Math.max(0, Math.min(98, Math.round(rawSolar)));
  const tempK = Math.round(42 + (solar / 100) * 205);

  // Direct-to-Earth (DTE) Visibility % calculation:
  // Earth sits near lon = 0° (plus optical libration in lon/lat).
  // Near-side longitudes (-90° to +90°) and high ridges (high lum, close to pole) have best Earth visibility.
  const dLonRad = (lon - state.earthLibLonDeg) * Math.PI / 180;
  const earthProjection = Math.cos(dLonRad); // +1 toward 0°E (Earth), -1 on far side (180°)
  const librationBonus = state.earthLibLatDeg * 1.9; // +/- 12.7% from Earth latitude libration
  const ridgeBonus = (lum - 0.35) * 42.0; // elevated sunlit ridges clear horizon obstacles
  const polarProximity = (1.0 - rNorm) * 28.0; // very close to 90°S pole sees Earth over the limb

  let earthVis = 52.0 + earthProjection * 34.0 + ridgeBonus + polarProximity * 0.5 + librationBonus - (slope * 0.65);
  if (lum < 0.18) earthVis -= 28.0; // deep crater floors have blocked horizon
  earthVis = Math.max(0, Math.min(99, Math.round(earthVis)));

  // Compute Landing Safety Index (LSI 0..100) against all 4 Lander Thresholds
  const p = state.params;
  const slopeRatio = slope / p.slopeMax;
  const clearRatio = roughness / p.clearanceMax;
  const solarDeficit = Math.max(0, p.solarMin - solar);
  const earthDeficit = Math.max(0, p.earthMin - earthVis);

  let score = 100;
  if (slopeRatio > 1.0) score -= 38 + (slopeRatio - 1.0) * 42;
  else score -= slopeRatio * 20;

  if (clearRatio > 1.0) score -= 32 + (clearRatio - 1.0) * 38;
  else score -= clearRatio * 15;

  if (solarDeficit > 0) score -= solarDeficit * 1.05;
  else score += Math.min(6, (solar - p.solarMin) * 0.18);

  if (earthDeficit > 0) score -= earthDeficit * 0.95;
  else score += Math.min(5, (earthVis - p.earthMin) * 0.15);

  score = Math.max(0, Math.min(100, Math.round(score)));
  const safetyFactor = +(p.slopeMax / Math.max(1.0, slope)).toFixed(2);
  const powerWatts = Math.round((solar / 100) * 1680);

  return {
    lat,
    lon,
    slope: +slope.toFixed(1),
    roughness: +roughness.toFixed(2),
    solar,
    earthVis,
    tempK,
    lsi: score,
    safetyFactor,
    powerWatts
  };
}

function rebuildThermalLayer() {
  const W = thermalCanvas.width;
  const H = thermalCanvas.height;
  const imgData = thermalCtx.createImageData(W, H);
  const buf = imgData.data;
  const cx = W / 2;
  const cy = H / 2;
  const diskR = W * 0.485;

  for (let py = 0; py < H; py++) {
    for (let px = 0; px < W; px++) {
      const nx = (px - cx) / diskR;
      const ny = (py - cy) / diskR;
      const r2 = nx * nx + ny * ny;
      const off = (py * W + px) * 4;

      if (r2 > 1.0) {
        buf[off + 3] = 0;
        continue;
      }

      const ev = evaluatePoint(nx, ny);
      let r, g, b, a;
      if (ev.lsi >= 75) {
        r = 16; g = 185; b = 129; a = 155;
      } else if (ev.lsi >= 45) {
        r = 245; g = 158; b = 11; a = 145;
      } else {
        r = 239; g = 68; b = 68; a = 175;
      }
      buf[off] = r;
      buf[off + 1] = g;
      buf[off + 2] = b;
      buf[off + 3] = a;
    }
  }
  thermalCtx.putImageData(imgData, 0, 0);
}

function getDiskScreenGeometry() {
  const w = canvas.width;
  const h = canvas.height;
  const baseRadius = Math.min(w, h) * 0.44;
  const r = baseRadius * state.zoom;
  const cx = w / 2 + state.panX;
  const cy = h / 2 + state.panY;
  return { cx, cy, r };
}

function render() {
  const w = canvas.width;
  const h = canvas.height;
  ctx.clearRect(0, 0, w, h);

  ctx.fillStyle = "#000000";
  ctx.fillRect(0, 0, w, h);

  const { cx, cy, r } = getDiskScreenGeometry();
  const imgDrawHalf = r / 0.97;

  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.clip();

  // Layer 1: Clean Clementine South Polar Base Map
  if (state.baseVisible && moonLoaded) {
    ctx.drawImage(
      moonImg,
      cx - imgDrawHalf,
      cy - imgDrawHalf,
      imgDrawHalf * 2,
      imgDrawHalf * 2
    );
  } else {
    ctx.fillStyle = "#090f1d";
    ctx.fillRect(cx - r, cy - r, r * 2, r * 2);
  }

  // Layer 2: Thermal Landing Safety Overlay
  if (state.thermalVisible) {
    ctx.save();
    ctx.globalAlpha = state.thermalOpacity;
    ctx.drawImage(
      thermalCanvas,
      cx - imgDrawHalf,
      cy - imgDrawHalf,
      imgDrawHalf * 2,
      imgDrawHalf * 2
    );
    ctx.restore();
  }

  // Subtle Selenographic Vector Reticle (always active cleanly on map)
  ctx.save();
  ctx.strokeStyle = "rgba(56, 189, 248, 0.22)";
  ctx.lineWidth = 1;
  ctx.setLineDash([4, 4]);

  [75, 80, 85].forEach(latAbs => {
    const rLat = r * (Math.sin((90 - latAbs) * Math.PI / 180) / SIN_20);
    ctx.beginPath();
    ctx.arc(cx, cy, rLat, 0, Math.PI * 2);
    ctx.stroke();
  });

  for (let deg = 0; deg < 180; deg += 30) {
    const rad = deg * Math.PI / 180;
    ctx.beginPath();
    ctx.moveTo(cx - r * Math.sin(rad), cy + r * Math.cos(rad));
    ctx.lineTo(cx + r * Math.sin(rad), cy - r * Math.cos(rad));
    ctx.stroke();
  }
  ctx.restore();

  ctx.restore();

  // Outer rim border (70°S)
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.strokeStyle = "rgba(56, 189, 248, 0.35)";
  ctx.lineWidth = 1.5;
  ctx.stroke();

  // External Selenographic Compass Degree Markers + Solar Direction Indicator
  if (r > 130) {
    ctx.save();
    ctx.font = "600 10px 'JetBrains Mono', monospace";
    ctx.fillStyle = "rgba(148, 163, 184, 0.85)";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    const isEs = state.lang === "es";
    const compassLabels = [
      { deg: 0, text: isEs ? "0° (TIERRA)" : "0° (EARTH)" },
      { deg: 90, text: "90°E" },
      { deg: 180, text: "180°" },
      { deg: -90, text: "90°W" }
    ];
    compassLabels.forEach(c => {
      const rad = c.deg * Math.PI / 180;
      const lx = cx + (r + 16) * Math.sin(rad);
      const ly = cy - (r + 16) * Math.cos(rad);
      if (lx > 30 && lx < w - 30 && ly > 15 && ly < h - 15) {
        ctx.fillText(c.text, lx, ly);
      }
    });

    // Draw Sun Azimuth beacon on perimeter
    const sunRad = state.sunAzimuthDeg * Math.PI / 180;
    const sunX = cx + (r + 14) * Math.sin(sunRad);
    const sunY = cy - (r + 14) * Math.cos(sunRad);
    ctx.beginPath();
    ctx.arc(sunX, sunY, 5, 0, Math.PI * 2);
    ctx.fillStyle = "#facc15";
    ctx.fill();
    ctx.strokeStyle = "#fef08a";
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.restore();
  }

  // Draw Artemis Candidate Site Pins
  ARTEMIS_SITES.forEach(site => {
    const pos = latLonToNorm(site.lat, site.lon);
    const sx = cx + pos.nx * r;
    const sy = cy + pos.ny * r;
    if (sx < -20 || sx > w + 20 || sy < -20 || sy > h + 20) return;

    ctx.beginPath();
    ctx.arc(sx, sy, 3.5, 0, Math.PI * 2);
    ctx.fillStyle = "#38bdf8";
    ctx.fill();
    ctx.strokeStyle = "#05080f";
    ctx.lineWidth = 1.2;
    ctx.stroke();

    if (state.zoom >= 1.6) {
      ctx.font = "600 10px Inter, sans-serif";
      ctx.fillStyle = "#e2e8f0";
      ctx.fillText(site.name.split(" ")[0], sx + 7, sy + 3);
    }
  });

  // Draw Multiple Optimal Zones (when user clicks "Buscar Zonas Óptimas")
  if (state.optimalZones && state.optimalZones.length > 0) {
    state.optimalZones.forEach((oz, idx) => {
      const pos = latLonToNorm(oz.lat, oz.lon);
      const ox = cx + pos.nx * r;
      const oy = cy + pos.ny * r;
      const isSelected = idx === state.activeOptIndex;

      ctx.save();
      ctx.beginPath();
      ctx.arc(ox, oy, isSelected ? 11 : 8, 0, Math.PI * 2);
      ctx.strokeStyle = isSelected ? "#ffffff" : "#10b981";
      ctx.lineWidth = isSelected ? 2.2 : 1.6;
      ctx.fillStyle = isSelected ? "rgba(16, 185, 129, 0.35)" : "rgba(16, 185, 129, 0.20)";
      ctx.fill();
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(ox, oy, 3.5, 0, Math.PI * 2);
      ctx.fillStyle = "#10b981";
      ctx.fill();

      // Label badge OPT-1..N
      const tag = `OPT-${idx + 1} (${oz.lsi})`;
      ctx.font = "700 10px 'JetBrains Mono', monospace";
      const tw = ctx.measureText(tag).width + 8;
      ctx.fillStyle = "rgba(5, 12, 24, 0.88)";
      ctx.fillRect(ox + 9, oy - 8, tw, 15);
      ctx.strokeStyle = "#10b981";
      ctx.lineWidth = 1;
      ctx.strokeRect(ox + 9, oy - 8, tw, 15);
      ctx.fillStyle = "#6ee7b7";
      ctx.fillText(tag, ox + 13, oy + 3);
      ctx.restore();
    });
  }

  // Draw Selected Target Reticle & Delta-V Divert Radius
  const sel = latLonToNorm(state.selectedLat, state.selectedLon);
  const tx = cx + sel.nx * r;
  const ty = cy + sel.ny * r;

  const divertKm = state.params.deltaV * 0.42;
  const divertPx = Math.max(14, (divertKm / 931.0) * r);

  ctx.save();
  ctx.beginPath();
  ctx.arc(tx, ty, divertPx, 0, Math.PI * 2);
  ctx.strokeStyle = "rgba(56, 189, 248, 0.75)";
  ctx.lineWidth = 1.2;
  ctx.setLineDash([4, 3]);
  ctx.stroke();
  ctx.fillStyle = "rgba(56, 189, 248, 0.08)";
  ctx.fill();
  ctx.restore();

  // Draw GNC divert trajectory if alternate safe site active
  if (state.altSite) {
    const alt = latLonToNorm(state.altSite.lat, state.altSite.lon);
    const ax = cx + alt.nx * r;
    const ay = cy + alt.ny * r;

    ctx.save();
    ctx.beginPath();
    ctx.moveTo(tx, ty);
    ctx.lineTo(ax, ay);
    ctx.strokeStyle = "#10b981";
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 3]);
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(ax, ay, 5.5, 0, Math.PI * 2);
    ctx.fillStyle = "#10b981";
    ctx.fill();
    ctx.strokeStyle = "#ffffff";
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.restore();
  }

  // Target Crosshair
  ctx.save();
  ctx.strokeStyle = "#ffffff";
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.arc(tx, ty, 8, 0, Math.PI * 2);
  ctx.moveTo(tx - 14, ty); ctx.lineTo(tx - 5, ty);
  ctx.moveTo(tx + 5, ty); ctx.lineTo(tx + 14, ty);
  ctx.moveTo(tx, ty - 14); ctx.lineTo(tx, ty - 5);
  ctx.moveTo(tx, ty + 5); ctx.lineTo(tx, ty + 14);
  ctx.stroke();
  ctx.restore();
}

function buildPlainLanguageLSIExplanation(ev) {
  const p = state.params;
  const isEs = state.lang === "es";
  const slopeOk = ev.slope <= p.slopeMax;
  const roughOk = ev.roughness <= p.clearanceMax;
  const solarOk = ev.solar >= p.solarMin;
  const earthOk = ev.earthVis >= p.earthMin;

  const fails = [];
  if (!slopeOk) {
    fails.push(isEs
      ? `la inclinación del terreno (${ev.slope}°) supera el límite de estabilidad del lander (${p.slopeMax}°), con riesgo de volcadura`
      : `ground slope (${ev.slope}°) exceeds the lander's tipping limit (${p.slopeMax}°)`);
  }
  if (!roughOk) {
    fails.push(isEs
      ? `las rocas locales (${ev.roughness} m) superan la altura libre de la tobera (${p.clearanceMax} m)`
      : `local boulders (${ev.roughness} m) exceed the nozzle ground clearance (${p.clearanceMax} m)`);
  }
  if (!solarOk) {
    fails.push(isEs
      ? `la luz solar (${ev.solar}%) es menor al mínimo requerido (${p.solarMin}%) para mantener las baterías y temperatura`
      : `solar illumination (${ev.solar}%) is below the required minimum (${p.solarMin}%) for power and thermal survival`);
  }
  if (!earthOk) {
    fails.push(isEs
      ? `la visibilidad hacia la Tierra (${ev.earthVis}%) no alcanza el mínimo de comunicaciones (${p.earthMin}%)`
      : `Earth visibility (${ev.earthVis}%) is below the minimum communication threshold (${p.earthMin}%)`);
  }

  if (ev.lsi >= 75 && fails.length === 0) {
    return isEs
      ? `Sitio óptimo para alunizar: el suelo es suficientemente plano (${ev.slope}° ≤ ${p.slopeMax}°), las rocas no comprometen la tobera (${ev.roughness} m ≤ ${p.clearanceMax} m), y cuenta con buena energía solar (${ev.solar}%) y enlace directo con la Tierra (${ev.earthVis}%).`
      : `Optimal landing site: terrain is flat enough (${ev.slope}° ≤ ${p.slopeMax}°), rocks clear the engine nozzle (${ev.roughness} m ≤ ${p.clearanceMax} m), with strong sunlight (${ev.solar}%) and direct Earth comms (${ev.earthVis}%).`;
  } else if (ev.lsi >= 45) {
    if (fails.length === 0) {
      return isEs
        ? `Sitio marginal: cumple raspando los límites del lander (${ev.slope}° de pendiente, ${ev.roughness} m de rugosidad, ${ev.solar}% sol y ${ev.earthVis}% visibilidad Tierra), pero con poco margen de seguridad.`
        : `Marginal site: barely meets the lander thresholds (${ev.slope}° slope, ${ev.roughness} m rocks, ${ev.solar}% sun, ${ev.earthVis}% Earth view) with narrow safety margins.`;
    }
    return isEs
      ? `Sitio riesgoso / marginal porque ${fails.join("; además, ")}. Se recomienda maniobra de desvío GNC.`
      : `Marginal / risky site because ${fails.join("; additionally, ")}. GNC divert maneuver recommended.`;
  } else {
    return isEs
      ? `Sitio NO apto para el lander: ${fails.length > 0 ? fails.join("; ") : "condiciones topográficas y térmicas extremas"}. El sistema GNC traza desvío automático.`
      : `Site NOT suitable for the lander: ${fails.length > 0 ? fails.join("; ") : "extreme topographic and thermal hazards"}. GNC system plots an automatic divert.`;
  }
}

function updateTelemetry() {
  const pos = latLonToNorm(state.selectedLat, state.selectedLon);
  const ev = evaluatePoint(pos.nx, pos.ny);
  if (!ev) return;

  const isEs = state.lang === "es";
  const scoreEl = document.getElementById("lsiScore");
  const verdictEl = document.getElementById("lsiVerdict");
  const descEl = document.getElementById("lsiPlainDesc");
  scoreEl.textContent = ev.lsi;

  if (ev.lsi >= 75) {
    scoreEl.style.color = "var(--green)";
    verdictEl.textContent = isEs ? "ZONA VIABLE PARA DESCENSO" : "VIABLE LANDING ZONE";
    verdictEl.style.background = "rgba(16,185,129,0.18)";
    verdictEl.style.color = "var(--green)";
    verdictEl.style.border = "1px solid rgba(16,185,129,0.4)";
    descEl.style.borderLeftColor = "var(--green)";
  } else if (ev.lsi >= 45) {
    scoreEl.style.color = "var(--amber)";
    verdictEl.textContent = isEs ? "ZONA MARGINAL — PRECAUCIÓN GNC" : "MARGINAL ZONE — GNC CAUTION";
    verdictEl.style.background = "rgba(245,158,11,0.18)";
    verdictEl.style.color = "var(--amber)";
    verdictEl.style.border = "1px solid rgba(245,158,11,0.4)";
    descEl.style.borderLeftColor = "var(--amber)";
  } else {
    scoreEl.style.color = "var(--red)";
    verdictEl.textContent = isEs ? "PELIGRO CRÍTICO / ABORTAR SITIO" : "CRITICAL HAZARD / ABORT SITE";
    verdictEl.style.background = "rgba(239,68,68,0.18)";
    verdictEl.style.color = "var(--red)";
    verdictEl.style.border = "1px solid rgba(239,68,68,0.4)";
    descEl.style.borderLeftColor = "var(--red)";
  }

  descEl.textContent = buildPlainLanguageLSIExplanation(ev);

  document.getElementById("selectedSiteTitle").textContent =
    `${state.selectedName} (${Math.abs(state.selectedLat).toFixed(2)}°S, ${state.selectedLon.toFixed(1)}°E)`;

  // Keep manual coordinate inputs synced with currently inspected point
  document.getElementById("inputLat").value = state.selectedLat.toFixed(2);
  document.getElementById("inputLon").value = state.selectedLon.toFixed(2);

  const slopeOk = ev.slope <= state.params.slopeMax;
  const roughOk = ev.roughness <= state.params.clearanceMax;
  const solarOk = ev.solar >= state.params.solarMin;
  const earthOk = ev.earthVis >= state.params.earthMin;

  const mSlope = document.getElementById("mSlope");
  mSlope.textContent = `${ev.slope}°`;
  mSlope.style.color = slopeOk ? "var(--green)" : "var(--red)";

  const mRough = document.getElementById("mRough");
  mRough.textContent = `${ev.roughness} m`;
  mRough.style.color = roughOk ? "var(--green)" : "var(--red)";

  const mSolar = document.getElementById("mSolar");
  mSolar.textContent = `${ev.solar}%`;
  mSolar.style.color = solarOk ? "var(--cyan)" : "var(--amber)";

  const mEarth = document.getElementById("mEarth");
  mEarth.textContent = `${ev.earthVis}%`;
  mEarth.style.color = earthOk ? "var(--green)" : "var(--red)";

  document.getElementById("mTemp").textContent = `${ev.tempK} K`;
  document.getElementById("mSafetyFactor").textContent = `${ev.safetyFactor}x`;
  document.getElementById("mSafetyFactor").style.color = ev.safetyFactor >= 1.25 ? "var(--green)" : "var(--red)";

  // GNC Diagnostic Log
  const logs = [];
  if (isEs) {
    logs.push(`[GNC] Objetivo: ${Math.abs(state.selectedLat).toFixed(2)}°S, ${state.selectedLon.toFixed(2)}°E`);
    logs.push(slopeOk
      ? `[OK] Pendiente ${ev.slope}° ≤ límite estable ${state.params.slopeMax}°`
      : `[ALERTA] Pendiente ${ev.slope}° excede límite de volcadura (${state.params.slopeMax}°)`);
    logs.push(roughOk
      ? `[OK] Rugosidad ${ev.roughness}m ≤ despeje tobera ${state.params.clearanceMax}m`
      : `[ALERTA] Rocas de ${ev.roughness}m comprometen tobera (${state.params.clearanceMax}m)`);
    logs.push(solarOk
      ? `[OK] Sol ${ev.solar}% genera ~${ev.powerWatts}W nominales`
      : `[AVISO] Sol ${ev.solar}% bajo mínimo (${state.params.solarMin}%)`);
    logs.push(earthOk
      ? `[OK] Visibilidad Tierra ${ev.earthVis}% ≥ umbral DTE ${state.params.earthMin}%`
      : `[AVISO] Visibilidad Tierra ${ev.earthVis}% insuficiente (<${state.params.earthMin}%)`);
  } else {
    logs.push(`[GNC] Target: ${Math.abs(state.selectedLat).toFixed(2)}°S, ${state.selectedLon.toFixed(2)}°E`);
    logs.push(slopeOk
      ? `[OK] Slope ${ev.slope}° ≤ tipping limit ${state.params.slopeMax}°`
      : `[ALERT] Slope ${ev.slope}° exceeds tipping limit (${state.params.slopeMax}°)`);
    logs.push(roughOk
      ? `[OK] Roughness ${ev.roughness}m ≤ nozzle clearance ${state.params.clearanceMax}m`
      : `[ALERT] Boulders (${ev.roughness}m) exceed nozzle clearance (${state.params.clearanceMax}m)`);
    logs.push(solarOk
      ? `[OK] Sunlight ${ev.solar}% yields ~${ev.powerWatts}W nominal`
      : `[WARN] Sunlight ${ev.solar}% below minimum (${state.params.solarMin}%)`);
    logs.push(earthOk
      ? `[OK] Earth visibility ${ev.earthVis}% ≥ DTE threshold ${state.params.earthMin}%`
      : `[WARN] Earth visibility ${ev.earthVis}% insufficient (<${state.params.earthMin}%)`);
  }

  state.altSite = null;
  if (ev.lsi < 72) {
    const alt = findNearestSafePoint(pos.nx, pos.ny);
    if (alt) {
      state.altSite = alt;
      logs.push(isEs
        ? `[DESVÍO GNC] Ruta alterna trazada a ${Math.abs(alt.lat).toFixed(2)}°S, ${alt.lon.toFixed(1)}°E (LSI: ${alt.lsi})`
        : `[GNC DIVERT] Alternate route plotted to ${Math.abs(alt.lat).toFixed(2)}°S, ${alt.lon.toFixed(1)}°E (LSI: ${alt.lsi})`);
    }
  }
  document.getElementById("gncLog").innerHTML = logs.join("<br>");
}

function findNearestSafePoint(nx0, ny0) {
  let best = null;
  for (let r = 0.015; r <= 0.16; r += 0.015) {
    for (let a = 0; a < Math.PI * 2; a += Math.PI / 12) {
      const nx = nx0 + r * Math.cos(a);
      const ny = ny0 + r * Math.sin(a);
      const geo = normToLatLon(nx, ny);
      if (!geo) continue;
      const ev = evaluatePoint(nx, ny);
      if (ev && ev.lsi >= 75) {
        if (!best || ev.lsi > best.lsi) {
          best = { lat: geo.lat, lon: geo.lon, lsi: ev.lsi };
        }
      }
    }
    if (best) return best;
  }
  return null;
}

// Exclusive Layer Control Guard: Only one layer can be disabled at a time, never both!
function onLayerChange(changedWhich) {
  const baseCheckbox = document.getElementById("toggleBaseLayer");
  const thermalCheckbox = document.getElementById("toggleThermalLayer");

  // Prevent both from being unchecked simultaneously
  if (!baseCheckbox.checked && !thermalCheckbox.checked) {
    if (changedWhich === "base") {
      thermalCheckbox.checked = true;
    } else {
      baseCheckbox.checked = true;
    }
  }

  state.baseVisible = baseCheckbox.checked;
  state.thermalVisible = thermalCheckbox.checked;

  document.getElementById("layerBaseCard").classList.toggle("active-layer", state.baseVisible);
  document.getElementById("layerThermalCard").classList.toggle("active-layer", state.thermalVisible);

  const activeCount = (state.baseVisible ? 1 : 0) + (state.thermalVisible ? 1 : 0);
  const isEs = state.lang === "es";
  document.getElementById("layerCountBadge").textContent =
    isEs ? `${activeCount} / 2 ACTIVAS` : `${activeCount} / 2 ACTIVE`;
  document.getElementById("legendBar").style.opacity = state.thermalVisible ? "1" : "0.25";

  const pureBtn = document.getElementById("pureMapBtn");
  const pureText = document.getElementById("pureMapBtnText");
  const t = I18N[state.lang];
  if (!state.thermalVisible && state.baseVisible) {
    pureBtn.classList.add("pure-active");
    pureText.textContent = t.pureBtnEnableBoth;
  } else {
    pureBtn.classList.remove("pure-active");
    pureText.textContent = t.pureBtnDisableThermal;
  }
  render();
}

function togglePureCircularMap() {
  const thermalCheckbox = document.getElementById("toggleThermalLayer");
  const baseCheckbox = document.getElementById("toggleBaseLayer");
  if (thermalCheckbox.checked) {
    baseCheckbox.checked = true;
    thermalCheckbox.checked = false;
  } else {
    baseCheckbox.checked = true;
    thermalCheckbox.checked = true;
  }
  onLayerChange("thermal");
}

function onOpacityChange(val) {
  state.thermalOpacity = val / 100;
  document.getElementById("opacityVal").textContent = `${val}%`;
  render();
}

function updateParams() {
  state.params.slopeMax = parseFloat(document.getElementById("paramSlope").value);
  state.params.clearanceMax = parseFloat(document.getElementById("paramClearance").value);
  state.params.solarMin = parseInt(document.getElementById("paramSolar").value, 10);
  state.params.earthMin = parseInt(document.getElementById("paramEarth").value, 10);
  state.params.deltaV = parseInt(document.getElementById("paramDeltaV").value, 10);

  document.getElementById("valSlope").textContent = `${state.params.slopeMax.toFixed(1)}°`;
  document.getElementById("valClearance").textContent = `${state.params.clearanceMax.toFixed(2)} m`;
  document.getElementById("valSolar").textContent = `${state.params.solarMin}%`;
  document.getElementById("valEarth").textContent = `${state.params.earthMin}%`;
  document.getElementById("valDeltaV").textContent = `${state.params.deltaV} m/s`;

  rebuildThermalLayer();
  updateTelemetry();
  render();
}

function resetDefaultParams() {
  document.getElementById("paramSlope").value = DEFAULT_PARAMS.slopeMax;
  document.getElementById("paramClearance").value = DEFAULT_PARAMS.clearanceMax;
  document.getElementById("paramSolar").value = DEFAULT_PARAMS.solarMin;
  document.getElementById("paramEarth").value = DEFAULT_PARAMS.earthMin;
  document.getElementById("paramDeltaV").value = DEFAULT_PARAMS.deltaV;
  state.optimalZones = [];
  state.activeOptIndex = -1;
  document.getElementById("optZonesBox").classList.remove("visible");
  updateParams();
}

// Multi-Zone Stochastic Optimal Search: Finds all optimal candidates and picks a random spatial subset of 5 zones
function findOptimalSites() {
  if (!imgBrightnessGrid && moonLoaded) {
    extractTerrainFromImage();
  }

  const candidates = [];
  // Escaneo directo en (nx, ny) para detectar TODOS los picos de 85-95 del mapa
  const step = 0.012;
  for (let ny = -0.98; ny <= 0.98; ny += step) {
    for (let nx = -0.98; nx <= 0.98; nx += step) {
      if (nx * nx + ny * ny > 0.98) continue;
      const ev = evaluatePoint(nx, ny);
      if (ev && ev.lsi > 0) {
        candidates.push({ lat: ev.lat, lon: ev.lon, nx, ny, lsi: ev.lsi });
      }
    }
  }

  candidates.sort((a, b) => b.lsi - a.lsi);

  // Debug real en consola (F12 -> Console)
  console.log("Imagen cargada:", moonLoaded, "| Grid listo:", !!imgBrightnessGrid);
  console.log("Top 10 LSI reales en el mapa:", candidates.slice(0, 10).map(c => c.lsi));

  // 1. Niveles estrictos: >= 85 y 80-89 (sin cortar tier2 a 3, para tener de dónde elegir separados)
  const tier1 = candidates.filter(c => c.lsi >= 85);
  const tier2 = candidates.filter(c => c.lsi >= 75 && c.lsi < 85);

  const shuffle = (arr) => {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  };

  let prioritizedPool = [
    ...shuffle([...tier1]),
    ...shuffle([...tier2])
  ];

  // Emergencia: solo si realmente hay menos de 3 puntos >= 80 en TODO el mapa
  if (prioritizedPool.length < 3) {
    console.warn("Emergencia: menos de 3 sitios >= 80 encontrados");
    prioritizedPool = candidates.slice(0, 5);
  }

  // 2. Elegir hasta 5 zonas separadas (sin ningún fallback posterior que meta puntajes bajos)
  const chosen = [];
  const minDistNorm = 0.14;
  for (const cand of prioritizedPool) {
    if (chosen.length >= 5) break;
    const tooClose = chosen.some(c => Math.hypot(c.nx - cand.nx, c.ny - cand.ny) < minDistNorm);
    if (!tooClose) {
      chosen.push(cand);
    }
  }

  chosen.sort((a, b) => b.lsi - a.lsi);
  state.optimalZones = chosen;
  state.activeOptIndex = 0;

  renderOptimalChips();

  if (chosen.length > 0) {
    selectOptimalZone(0, false);
    state.zoom = 1.25;
    state.panX = 0;
    state.panY = 0;
    document.getElementById("zoomTag").textContent = "1.3x";
    render();
  }
}

function renderOptimalChips() {
  const box = document.getElementById("optZonesBox");
  const container = document.getElementById("optChipsContainer");
  container.innerHTML = "";

  if (!state.optimalZones || state.optimalZones.length === 0) {
    box.classList.remove("visible");
    return;
  }

  box.classList.add("visible");
  state.optimalZones.forEach((oz, idx) => {
    const chip = document.createElement("button");
    chip.className = "opt-chip" + (idx === state.activeOptIndex ? " active" : "");
    chip.textContent = `OPT-${idx + 1}: ${Math.abs(oz.lat).toFixed(1)}°S, ${oz.lon.toFixed(0)}°E (LSI ${oz.lsi})`;
    chip.onclick = () => selectOptimalZone(idx, true);
    container.appendChild(chip);
  });
}

function selectOptimalZone(idx, zoomToZone = true) {
  const oz = state.optimalZones[idx];
  if (!oz) return;
  state.activeOptIndex = idx;
  state.selectedLat = oz.lat;
  state.selectedLon = oz.lon;
  state.selectedName = state.lang === "es"
    ? `Zona Óptima OPT-${idx + 1}`
    : `Optimal Zone OPT-${idx + 1}`;
  document.querySelectorAll(".site-btn").forEach(b => b.classList.remove("active-site"));
  renderOptimalChips();
  if (zoomToZone) {
    centerOnLatLon(oz.lat, oz.lon, Math.max(state.zoom, 2.8));
  }
  updateTelemetry();
  render();
}

// Manual Coordinates Entry Handler
function goToManualCoords() {
  let rawLat = parseFloat(document.getElementById("inputLat").value);
  let rawLon = parseFloat(document.getElementById("inputLon").value);
  if (isNaN(rawLat)) rawLat = -89.54;
  if (isNaN(rawLon)) rawLon = 0.0;

  // Accept either positive (e.g. 85.0 for 85°S) or negative (-85.0)
  let lat = rawLat > 0 ? -rawLat : rawLat;
  lat = Math.max(-90.0, Math.min(-70.0, lat));
  let lon = Math.max(-180.0, Math.min(180.0, rawLon));

  state.selectedLat = lat;
  state.selectedLon = lon;
  state.selectedName = state.lang === "es"
    ? "Coordenada Manual"
    : "Manual Coordinate";
  state.activeOptIndex = -1;
  renderOptimalChips();
  document.querySelectorAll(".site-btn").forEach(b => b.classList.remove("active-site"));

  centerOnLatLon(lat, lon, Math.max(state.zoom, 3.0));
  updateTelemetry();
  render();
}

// Language Switcher (ES <-> EN)
function toggleLanguage() {
  state.lang = state.lang === "es" ? "en" : "es";
  document.getElementById("langEs").classList.toggle("active", state.lang === "es");
  document.getElementById("langEn").classList.toggle("active", state.lang === "en");

  const t = I18N[state.lang];
  const htmlKeys = ["tSlopeLbl", "tClearLbl"];
  Object.keys(t).forEach(key => {
    const el = document.getElementById(key);
    if (!el) return;
    if (htmlKeys.includes(key)) el.innerHTML = t[key];
    else el.textContent = t[key];
  });

  onLayerChange("none");
  updateEphemerisUI();
  initSiteList();
  renderOptimalChips();
  updateTelemetry();
  render();
}

// Vector Zoom & Pan Controls
function zoomBy(factor, pivotX = canvas.width / 2, pivotY = canvas.height / 2) {
  const newZoom = Math.max(0.85, Math.min(18.0, state.zoom * factor));
  const ratio = newZoom / state.zoom;
  const cx = canvas.width / 2 + state.panX;
  const cy = canvas.height / 2 + state.panY;

  state.panX = pivotX - ratio * (pivotX - cx) - canvas.width / 2;
  state.panY = pivotY - ratio * (pivotY - cy) - canvas.height / 2;
  state.zoom = newZoom;

  document.getElementById("zoomTag").textContent = `${state.zoom.toFixed(1)}x`;
  render();
}

function resetView() {
  state.zoom = 1.0;
  state.panX = 0;
  state.panY = 0;
  document.getElementById("zoomTag").textContent = "1.0x";
  render();
}

function centerOnLatLon(lat, lon, targetZoom = 3.5) {
  state.zoom = targetZoom;
  document.getElementById("zoomTag").textContent = `${state.zoom.toFixed(1)}x`;
  const baseRadius = Math.min(canvas.width, canvas.height) * 0.44 * state.zoom;
  const pos = latLonToNorm(lat, lon);
  state.panX = -pos.nx * baseRadius;
  state.panY = -pos.ny * baseRadius;
}

viewport.addEventListener("wheel", (e) => {
  e.preventDefault();
  const rect = canvas.getBoundingClientRect();
  const mx = e.clientX - rect.left;
  const my = e.clientY - rect.top;
  const factor = e.deltaY < 0 ? 1.22 : 1 / 1.22;
  zoomBy(factor, mx, my);
}, { passive: false });

let downX = 0, downY = 0;
viewport.addEventListener("mousedown", (e) => {
  state.isDragging = true;
  downX = e.clientX;
  downY = e.clientY;
  state.dragStartX = e.clientX - state.panX;
  state.dragStartY = e.clientY - state.panY;
});

window.addEventListener("mousemove", (e) => {
  const rect = canvas.getBoundingClientRect();
  const mx = e.clientX - rect.left;
  const my = e.clientY - rect.top;

  if (state.isDragging) {
    state.panX = e.clientX - state.dragStartX;
    state.panY = e.clientY - state.dragStartY;
    render();
    return;
  }

  if (mx >= 0 && mx <= canvas.width && my >= 0 && my <= canvas.height) {
    const { cx, cy, r } = getDiskScreenGeometry();
    const nx = (mx - cx) / r;
    const ny = (my - cy) / r;
    const geo = normToLatLon(nx, ny);
    const isEs = state.lang === "es";
    if (geo) {
      document.getElementById("hudCoords").textContent =
        `${Math.abs(geo.lat).toFixed(2)}°S, ${geo.lon.toFixed(2)}°E`;
      document.getElementById("hudFeature").textContent =
        geo.lat < -88.5
          ? (isEs ? "Sector Polar Central (Shackleton)" : "Central Polar Sector (Shackleton)")
          : geo.lat < -83.0
            ? (isEs ? "Anillo Interior Polo Sur (80°S–88°S)" : "Inner South Polar Ring (80°S–88°S)")
            : (isEs ? "Sector Exterior Polo Sur (70°S–83°S)" : "Outer South Polar Sector (70°S–83°S)");
    } else {
      document.getElementById("hudCoords").textContent = isEs ? "FUERA DE DISCO (>70°S)" : "OUTSIDE DISK (>70°S)";
      document.getElementById("hudFeature").textContent = isEs ? "Espacio Profundo" : "Deep Space";
    }
  }
});

window.addEventListener("mouseup", (e) => {
  if (!state.isDragging) return;
  state.isDragging = false;
  const moved = Math.hypot(e.clientX - downX, e.clientY - downY);
  if (moved < 5) {
    const rect = canvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;
    const { cx, cy, r } = getDiskScreenGeometry();

    // Check if user clicked on one of the displayed OPT markers first
    if (state.optimalZones && state.optimalZones.length > 0) {
      for (let i = 0; i < state.optimalZones.length; i++) {
        const oz = state.optimalZones[i];
        const pos = latLonToNorm(oz.lat, oz.lon);
        const ox = cx + pos.nx * r;
        const oy = cy + pos.ny * r;
        if (Math.hypot(mx - ox, my - oy) <= 13) {
          selectOptimalZone(i, false);
          return;
        }
      }
    }

    const nx = (mx - cx) / r;
    const ny = (my - cy) / r;
    const geo = normToLatLon(nx, ny);
    if (geo) {
      state.selectedLat = geo.lat;
      state.selectedLon = geo.lon;
      state.selectedName = state.lang === "es" ? "Punto Seleccionado en Mapa" : "Map Selected Point";
      state.activeOptIndex = -1;
      renderOptimalChips();
      document.querySelectorAll(".site-btn").forEach(b => b.classList.remove("active-site"));
      updateTelemetry();
      render();
    }
  }
});

function initSiteList() {
  const container = document.getElementById("siteList");
  container.innerHTML = "";
  const isEs = state.lang === "es";
  ARTEMIS_SITES.forEach((site, idx) => {
    const btn = document.createElement("button");
    const isActive = Math.abs(state.selectedLat - site.lat) < 0.02 && Math.abs(state.selectedLon - site.lon) < 0.02;
    btn.className = "site-btn" + (isActive || (idx === 0 && !state.selectedLat) ? " active-site" : "");
    const displayName = isEs ? site.name : site.nameEn;
    btn.innerHTML = `
      <div>
        <div class="site-name">${displayName}</div>
        <div class="site-coords">${Math.abs(site.lat).toFixed(2)}°S, ${site.lon.toFixed(1)}°E</div>
      </div>
      <span class="widget-badge">${site.tag}</span>
    `;
    btn.onclick = () => {
      document.querySelectorAll(".site-btn").forEach(b => b.classList.remove("active-site"));
      btn.classList.add("active-site");
      state.activeOptIndex = -1;
      renderOptimalChips();
      selectSite(site, true);
    };
    container.appendChild(btn);
  });
}

function selectSite(site, zoomIn = true) {
  state.selectedLat = site.lat;
  state.selectedLon = site.lon;
  state.selectedName = state.lang === "es" ? site.name : site.nameEn;
  if (zoomIn) centerOnLatLon(site.lat, site.lon, 3.6);
  updateTelemetry();
  render();
}

function resizeCanvas() {
  canvas.width = viewport.clientWidth;
  canvas.height = viewport.clientHeight;
  render();
}

window.addEventListener("resize", resizeCanvas);
initSiteList();
resizeCanvas();